def can_form_beautiful_sequence(k, q):
    if len(set(q)) < k:
        return "NO"

    def backtrack(start, path):
        if len(path) == k:
            return path

        used_chars = set(s[0] for s in path)
        for i in range(start, len(q)):
            if q[i] not in used_chars:
                new_path = path + [q[i:]]
                result = backtrack(i + 1, new_path)
                if result:
                    return result
        return None

    result = backtrack(0, [])
    if result:
        return "YES\n" + "\n".join(result)
    else:
        return "NO"

